// ============================================================
// PREMIUM MODAL & PURCHASE FLOW
// ============================================================
// Opens the Premium modal. If a featureKey is provided, it highlights the
// relevant feature (used by requirePremium() from gated features).
function openPremiumModal(featureKey) {
  updatePremiumUI();
  openModal('premium-modal');
}

// Updates the Premium modal + Settings Hub badge to reflect current status.
function updatePremiumUI() {
  const active = isPremium();
  const banner = document.getElementById('premium-active-banner');
  const buyBtn = document.getElementById('premium-purchase-btn');
  const badge = document.getElementById('hub-premium-badge');
  const subtitle = document.getElementById('hub-premium-subtitle');

  if (banner) banner.style.display = active ? 'block' : 'none';
  if (buyBtn) buyBtn.style.display = active ? 'none' : 'block';
  if (badge) {
    badge.textContent = active
      ? (state.lang === 'el' ? 'Ενεργό' : 'Active')
      : (state.lang === 'el' ? 'Αναβάθμισε' : 'Upgrade');
    badge.style.background = active ? 'rgba(34,197,94,0.2)' : 'rgba(255,193,7,0.2)';
    badge.style.color = active ? '#22c55e' : '#ffc107';
  }
  if (subtitle) {
    subtitle.textContent = active
      ? (state.lang === 'el' ? 'Όλα τα features ξεκλειδωμένα' : 'All features unlocked')
      : (state.lang === 'el' ? 'Ξεκλείδωσε όλα τα features — εφάπαξ' : 'Unlock all features — one-time');
  }
}

// Starts the premium purchase flow.
// - Native Android (Capacitor): Google Play Billing via the `capacitor-billing`
//   plugin. The purchase token is verified server-side by /api/play-billing.
// - Web / PWA: Stripe Checkout via /api/purchase.
// Falls back to a manual-activation notice if the endpoint is not deployed.
async function startPremiumPurchase() {
  if (isPremium()) {
    showSyncToast(state.lang === 'el' ? '✓ Είσαι ήδη Premium!' : '✓ You are already Premium!', 2500);
    return;
  }
  if (!state.currentUser) {
    showSyncToast(state.lang === 'el' ? '⚠️ Συνδέσου πρώτα για να αγοράσεις Premium.' : '⚠️ Please sign in first to purchase Premium.', 3500);
    return;
  }

  const btn = document.getElementById('premium-purchase-btn');
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = state.lang === 'el' ? 'Προετοιμασία...' : 'Preparing...';
  }

  try {
    // Native Android → Google Play Billing.
    if (typeof window.Capacitor !== 'undefined' && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform()) {
      const Billing = getBillingPlugin();
      if (Billing) {
        await purchasePremiumViaPlayBilling(Billing);
        return;
      }
      // Plugin unavailable on native → fall through to web flow with a notice.
      showSyncToast(state.lang === 'el' ? '⚠️ Το Google Play Billing δεν είναι διαθέσιμο.' : '⚠️ Google Play Billing is not available.', 3500);
      return;
    }

    // Web / PWA → Stripe Checkout.
    // Resolve the current session token for the Authorization header.
    let accessToken = '';
    if (state.supabaseClient) {
      try {
        const { data } = await state.supabaseClient.auth.getSession();
        if (data && data.session && data.session.access_token) {
          accessToken = data.session.access_token;
        }
      } catch (e) {
        console.warn('Could not resolve session token for purchase:', e);
      }
    }
    if (!accessToken) {
      showSyncToast(state.lang === 'el' ? '⚠️ Συνδέσου πρώτα για να αγοράσεις Premium.' : '⚠️ Please sign in first to purchase Premium.', 3500);
      return;
    }

    const res = await fetch('/api/purchase', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + accessToken
      },
      body: JSON.stringify({ userId: state.currentUser.id })
    });
    const data = await res.json().catch(() => ({}));

    if (res.ok && data.url) {
      // Redirect to Stripe Checkout
      window.location.href = data.url;
      return;
    }
    // Endpoint not deployed / error → manual activation fallback
    console.warn('Premium purchase endpoint unavailable:', data);
    showSyncToast(
      state.lang === 'el'
        ? '⚠️ Η πληρωμή δεν είναι ακόμα ενεργή. Επικοινώνησε με τον διαχειριστή.'
        : '⚠️ Payment is not active yet. Please contact the administrator.',
      5000
    );
  } catch (err) {
    console.error('Premium purchase error:', err);
    showSyncToast(state.lang === 'el' ? '⚠️ Σφάλμα κατά την αγορά.' : '⚠️ Purchase error.', 3500);
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = `<i class="fa-solid fa-crown" style="margin-right:6px;"></i><span>${state.lang === 'el' ? 'Αγορά για 9,99 €' : 'Buy for €9.99'}</span>`;
    }
  }
}

// Resolve the capacitor-billing plugin (BillingPlugin) if present on native.
function getBillingPlugin() {
  if (typeof window.Capacitor === 'undefined') return null;
  if (window.Capacitor.Plugins && window.Capacitor.Plugins.BillingPlugin) {
    return window.Capacitor.Plugins.BillingPlugin;
  }
  if (typeof window.Capacitor.registerPlugin === 'function') {
    try {
      return window.Capacitor.registerPlugin('BillingPlugin');
    } catch (e) {
      console.warn('Could not register BillingPlugin:', e);
      return null;
    }
  }
  return null;
}

// Native Android purchase via Google Play Billing. Launches the Play purchase
// sheet for the Premium Lifetime one-time product, then verifies the returned
// purchase token server-side and grants the entitlement.
async function purchasePremiumViaPlayBilling(Billing) {
  const PRODUCT_ID = 'premium_lifetime';
  const PRODUCT_TYPE = 'INAPP'; // one-time purchase (Premium Lifetime)

  try {
    const result = await Billing.launchBillingFlow({
      product: PRODUCT_ID,
      type: PRODUCT_TYPE
    });

    // On Android the plugin resolves with the purchase's original JSON, which
    // contains the purchaseToken. On web it returns { value: 'web' } (unsupported).
    if (!result || result.value === 'web') {
      showSyncToast(state.lang === 'el' ? '⚠️ Η αγορά δεν ολοκληρώθηκε.' : '⚠️ Purchase was not completed.', 3500);
      return;
    }

    const purchaseToken = result.purchaseToken;
    if (!purchaseToken) {
      console.warn('Play Billing purchase resolved without a purchaseToken:', result);
      showSyncToast(state.lang === 'el' ? '⚠️ Η αγορά δεν ολοκληρώθηκε.' : '⚠️ Purchase was not completed.', 3500);
      return;
    }

    // Acknowledge the purchase (required within 3 days for one-time products).
    try {
      await Billing.sendAck({ purchaseToken });
    } catch (ackErr) {
      console.warn('Play Billing sendAck failed (will retry later):', ackErr.message);
    }

    // Verify server-side and grant entitlement.
    const ok = await verifyPlayBillingPurchase(purchaseToken, PRODUCT_ID);
    if (ok) {
      await loadUserProfiles(state.currentUser);
      updatePremiumUI();
      showSyncToast(state.lang === 'el' ? '✓ Το Premium ενεργοποιήθηκε!' : '✓ Premium activated!', 3000);
    } else {
      showSyncToast(state.lang === 'el' ? '⚠️ Δεν ήταν δυνατή η επαλήθευση της αγοράς.' : '⚠️ Could not verify the purchase.', 4000);
    }
  } catch (err) {
    // USER_CANCELED is surfaced as a rejection by the plugin.
    console.warn('Play Billing purchase error:', err && err.message ? err.message : err);
    showSyncToast(state.lang === 'el' ? '⚠️ Η αγορά ακυρώθηκε.' : '⚠️ Purchase cancelled.', 3000);
  }
}

// Verify a Google Play purchase token server-side (/api/play-billing) and grant
// the Premium entitlement. Returns true when the server confirmed premium_active.
async function verifyPlayBillingPurchase(purchaseToken, productId) {
  if (!state.currentUser || !state.supabaseClient) return false;
  try {
    const { data: sessionData } = await state.supabaseClient.auth.getSession();
    const token = sessionData && sessionData.session ? sessionData.session.access_token : null;
    if (!token) return false;

    const res = await fetch('/api/play-billing', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      },
      body: JSON.stringify({ purchaseToken, productId })
    });
    const data = await res.json().catch(() => ({}));
    return !!(res.ok && data && data.ok && data.premium_active);
  } catch (err) {
    console.warn('Play Billing verification error:', err.message);
    return false;
  }
}

// Restores a previously purchased Premium (Android / Google Play).
async function restorePremiumPurchase() {
  if (!state.currentUser) {
    showSyncToast(state.lang === 'el' ? '⚠️ Συνδέσου πρώτα για να επαναφέρεις το Premium.' : '⚠️ Please sign in first to restore Premium.', 3500);
    return;
  }

  // Native Android: the capacitor-billing plugin has no restorePurchases()
  // method, so we rely on server-side reconciliation (/api/premium-status).
  // That endpoint re-reads the profile (source of truth) and reconciles any
  // previously granted entitlement, so a reinstall / re-login picks it up.
  if (typeof window.Capacitor !== 'undefined' && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform()) {
    const restored = await reconcilePremiumPurchase();
    await loadUserProfiles(state.currentUser);
    updatePremiumUI();
    if (restored || isPremium()) {
      showSyncToast(state.lang === 'el' ? '✓ Το Premium επαναφέρθηκε.' : '✓ Premium restored.', 3000);
    } else {
      showSyncToast(state.lang === 'el' ? '⚠️ Δεν βρέθηκε ενεργό Premium.' : '⚠️ No active Premium found.', 3500);
    }
    return;
  }

  // Web: first try server-side reconciliation (/api/premium-status). This
  // queries Stripe for the user's paid sessions and grants the entitlement if
  // the webhook was lost. Then re-fetch the profile (server is source of truth).
  await reconcilePremiumPurchase();
  await loadUserProfiles(state.currentUser);
  updatePremiumUI();
  showSyncToast(state.lang === 'el' ? '✓ Το Premium ανανεώθηκε.' : '✓ Premium refreshed.', 2500);
}

// Call the server-side reconciliation endpoint. It queries Stripe for the
// authenticated user's paid Checkout Sessions and grants the entitlement if a
// paid session exists but the profile isn't premium (webhook-lost recovery).
// Returns true if the server reported premium_active after reconciliation.
async function reconcilePremiumPurchase() {
  if (!state.currentUser || !state.supabaseClient) return false;
  try {
    const { data: sessionData } = await state.supabaseClient.auth.getSession();
    const token = sessionData && sessionData.session ? sessionData.session.access_token : null;
    if (!token) return false;

    // Short retry loop: the webhook may still be processing, so give it a few
    // attempts before giving up. Each attempt is idempotent.
    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        const res = await fetch('/api/premium-status', {
          method: 'GET',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        if (res.ok) {
          const data = await res.json().catch(() => ({}));
          if (data && data.premium_active) {
            return true;
          }
        }
      } catch (err) {
        console.warn('Premium reconciliation attempt failed:', err.message);
      }
      if (attempt < 2) {
        await new Promise(r => setTimeout(r, 1500));
      }
    }
    return false;
  } catch (err) {
    console.warn('Premium reconciliation error:', err);
    return false;
  }
}

window.openPremiumModal = openPremiumModal;
window.updatePremiumUI = updatePremiumUI;
window.startPremiumPurchase = startPremiumPurchase;
window.restorePremiumPurchase = restorePremiumPurchase;

// Floating toast for background sync feedback
let _syncToastTimer = null;
function showSyncToast(message, autoDismissMs = 0) {
  let toast = document.getElementById('sync-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'sync-toast';
    toast.style.cssText = `
      position: fixed; bottom: 24px; right: 20px; z-index: 99999;
      background: var(--card-bg, #1e1e2e); color: var(--text-primary, #fff);
      border: 1px solid var(--accent, #7c6af7); border-radius: 14px;
      padding: 12px 18px; font-size: 13px; font-weight: 600;
      box-shadow: 0 8px 32px rgba(0,0,0,0.4);
      display: flex; align-items: center; gap: 10px;
      transform: translateY(80px); opacity: 0;
      transition: transform 0.3s cubic-bezier(.34,1.56,.64,1), opacity 0.3s ease;
      max-width: 280px;
    `;
    document.body.appendChild(toast);
  }
  // Animated pulse dot
  toast.innerHTML = `<span style="width:8px;height:8px;border-radius:50%;background:var(--accent,#7c6af7);display:inline-block;animation:syncPulse 1s infinite;flex-shrink:0;"></span><span>${message}</span>`;
  // Inject keyframes if not already
  if (!document.getElementById('sync-toast-styles')) {
    const s = document.createElement('style');
    s.id = 'sync-toast-styles';
    s.textContent = `@keyframes syncPulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.4;transform:scale(1.4)} }`;
    document.head.appendChild(s);
  }
  // Show
  requestAnimationFrame(() => {
    toast.style.transform = 'translateY(0)';
    toast.style.opacity = '1';
  });
  // Update header sync icon based on message type
  if (message.startsWith('✅')) {
    updateHeaderSyncIcon('synced');
    const dot = toast.querySelector('span');
    if (dot) dot.style.animation = 'none';
  } else if (message.startsWith('⚠️')) {
    updateHeaderSyncIcon('error');
    const dot = toast.querySelector('span');
    if (dot) dot.style.animation = 'none';
  } else if (message.startsWith('☁️')) {
    updateHeaderSyncIcon('syncing');
  }
  if (_syncToastTimer) clearTimeout(_syncToastTimer);
  if (autoDismissMs > 0) {
    _syncToastTimer = setTimeout(() => {
      toast.style.transform = 'translateY(80px)';
      toast.style.opacity = '0';
    }, autoDismissMs);
  }
}
function updateHeaderSyncIcon(state_) {
  state.syncStatus = state_;
  // state_: 'offline' | 'idle' | 'syncing' | 'synced' | 'success' | 'error'
  const dot = document.getElementById('header-sync-dot');
  const icon = document.getElementById('header-sync-cloud-icon');
  if (!dot || !icon) return;

  // Normalize state for visual elements and translations
  let normalized = state_;
  if (state_ === 'success') normalized = 'synced';
  if (state_ === 'idle') normalized = 'offline';

  const colors = {
    offline: '#9e9e9e',
    syncing: '#ffd600',
    synced: '#4caf50',
    error: '#ef5350'
  };
  dot.style.background = colors[normalized] || '#9e9e9e';

  // Animate dot on sync
  if (normalized === 'syncing') {
    dot.style.animation = 'syncDotPulse 0.8s infinite alternate';
  } else {
    dot.style.animation = 'none';
  }

  // Inject dot keyframes once
  if (!document.getElementById('sync-dot-styles')) {
    const s = document.createElement('style');
    s.id = 'sync-dot-styles';
    s.textContent = `@keyframes syncDotPulse{from{opacity:1;transform:scale(1)}to{opacity:.3;transform:scale(1.6)}}`;
    document.head.appendChild(s);
  }

  // Tooltip
  const btn = document.getElementById('header-sync-icon');
  const lang = state.lang || 'el';
  const labels = lang === 'en' ? {
    offline: 'Local Storage',
    syncing: 'Syncing...',
    synced: 'Synced ✅',
    error: 'Sync Error ⚠️'
  } : {
    offline: 'Τοπική αποθήκευση',
    syncing: 'Συγχρονισμός...',
    synced: 'Συγχρονισμένο ✅',
    error: 'Σφάλμα συγχρονισμού ⚠️'
  };
  if (btn) btn.title = labels[normalized] || (lang === 'en' ? 'Sync' : 'Συγχρονισμός');

  // Update sync status text in settings
  const syncStatusEl = document.getElementById('val_sync_status');
  if (syncStatusEl) {
    const statusLabels = lang === 'en' ? {
      offline: 'Local Storage',
      syncing: 'Syncing...',
      synced: 'Active',
      error: 'Error'
    } : {
      offline: 'Τοπική Αποθήκευση',
      syncing: 'Συγχρονισμός...',
      synced: 'Ενεργός',
      error: 'Σφάλμα'
    };
    syncStatusEl.textContent = statusLabels[normalized] || (lang === 'en' ? 'Local Storage' : 'Τοπική Αποθήκευση');

    // Update color based on status
    if (normalized === 'synced') {
      syncStatusEl.style.color = '#4caf50'; // Green for active
    } else if (normalized === 'error') {
      syncStatusEl.style.color = '#ef5350'; // Red for error
    } else {
      syncStatusEl.style.color = 'var(--text-secondary)';
    }
  }
}

function promiseTimeout(promise, ms) {
  let timeout = new Promise((resolve, reject) => {
    let id = setTimeout(() => {
      clearTimeout(id);
      reject(new Error('Διακοπή λόγω καθυστέρησης (Timeout - Η υπηρεσία Cloud καθυστερεί να απαντήσει)'));
    }, ms);
  });
  return Promise.race([promise, timeout]);
}

// ============================================================
// UTILITIES
// ============================================================
function formatCurrency(val) {
  if (localStorage.getItem('settings_hide_amounts') === 'true') return '*** €';
  if (isNaN(val)) return '0,00';
  return parseFloat(val).toLocaleString('el-GR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function updateExportSheetDateLabels() {
  const now = new Date();

  const curMonthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const curMonthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  const curMonthEl = document.getElementById('export-range-current-month');
  if (curMonthEl) curMonthEl.textContent = `(${formatShortDate(curMonthStart)} ~ ${formatShortDate(curMonthEnd)})`;

  const prevMonthStart = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const prevMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0);
  const prevMonthEl = document.getElementById('export-range-prev-month');
  if (prevMonthEl) prevMonthEl.textContent = `(${formatShortDate(prevMonthStart)} ~ ${formatShortDate(prevMonthEnd)})`;

  const curYearStart = new Date(now.getFullYear(), 0, 1);
  const curYearEnd = now;
  const curYearEl = document.getElementById('export-range-current-year');
  if (curYearEl) curYearEl.textContent = `(${formatShortDate(curYearStart)} ~ ${formatShortDate(curYearEnd)})`;

  const prevYearStart = new Date(now.getFullYear() - 1, 0, 1);
  const prevYearEnd = new Date(now.getFullYear() - 1, 11, 31);
  const prevYearEl = document.getElementById('export-range-prev-year');
  if (prevYearEl) prevYearEl.textContent = `(${formatShortDate(prevYearStart)} ~ ${formatShortDate(prevYearEnd)})`;
}

let selectedExportPeriod = 'current-month';
let selectedExportFormat = 'xlsx';

function openExportPeriodSheet() {
  if (typeof closeSearchBottomSheet === 'function') {
    closeSearchBottomSheet(true);
  }

  updateExportSheetDateLabels();

  const backdrop = document.getElementById('export-period-backdrop');
  if (backdrop) backdrop.classList.add('active');

  const sheet = document.getElementById('export-period-bottom-sheet');
  if (sheet) sheet.classList.add('active');

  // Reset to step 1
  const step1 = document.getElementById('export-step-1');
  const step2 = document.getElementById('export-step-2');
  if (step1) step1.style.display = 'block';
  if (step2) step2.style.display = 'none';

  selectExportOption('current-month', false);

  const today = new Date();
  const yyyy = today.getFullYear();
  const mm = String(today.getMonth() + 1).padStart(2, '0');
  const dd = String(today.getDate()).padStart(2, '0');
  const todayStr = `${yyyy}-${mm}-${dd}`;
  const displayStr = `${dd}/${mm}/${yyyy}`;

  const fromEl = document.getElementById('export-custom-from');
  const toEl = document.getElementById('export-custom-to');
  const fromLabel = document.getElementById('export-custom-from-label');
  const toLabel = document.getElementById('export-custom-to-label');

  if (fromEl) fromEl.value = todayStr;
  if (toEl) toEl.value = todayStr;
  if (fromLabel) fromLabel.textContent = displayStr;
  if (toLabel) toLabel.textContent = displayStr;
}

function closeExportPeriodSheet() {
  const sheet = document.getElementById('export-period-bottom-sheet');
  if (sheet) sheet.classList.remove('active');

  const backdrop = document.getElementById('export-period-backdrop');
  if (backdrop) backdrop.classList.remove('active');
}

function goToExportStep1() {
  const step1 = document.getElementById('export-step-1');
  const step2 = document.getElementById('export-step-2');
  if (step1) step1.style.display = 'block';
  if (step2) step2.style.display = 'none';
}
window.goToExportStep1 = goToExportStep1;

function updateStep2Summary() {
  const now = new Date();
  let startDate = null;
  let endDate = null;
  let periodText = '';

  if (selectedExportPeriod === 'current-month') {
    startDate = new Date(now.getFullYear(), now.getMonth(), 1);
    endDate = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    periodText = (state.lang === 'en' ? 'Current Month' : 'Τρέχων Μήνας') + ` (${formatShortDate(startDate)} ~ ${formatShortDate(endDate)})`;
  } else if (selectedExportPeriod === 'prev-month') {
    startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    endDate = new Date(now.getFullYear(), now.getMonth(), 0);
    periodText = (state.lang === 'en' ? 'Previous Month' : 'Προηγούμενος Μήνας') + ` (${formatShortDate(startDate)} ~ ${formatShortDate(endDate)})`;
  } else if (selectedExportPeriod === 'current-year') {
    startDate = new Date(now.getFullYear(), 0, 1);
    endDate = now;
    periodText = (state.lang === 'en' ? 'Current Year' : 'Τρέχων Έτος') + ` (${formatShortDate(startDate)} ~ ${formatShortDate(endDate)})`;
  } else if (selectedExportPeriod === 'prev-year') {
    startDate = new Date(now.getFullYear() - 1, 0, 1);
    endDate = new Date(now.getFullYear() - 1, 11, 31);
    periodText = (state.lang === 'en' ? 'Previous Year' : 'Προηγούμενο Έτος') + ` (${formatShortDate(startDate)} ~ ${formatShortDate(endDate)})`;
  } else if (selectedExportPeriod === 'all') {
    periodText = state.lang === 'en' ? 'All Data' : 'Όλα τα δεδομένα';
  } else if (selectedExportPeriod === 'custom') {
    const fromStr = document.getElementById('export-custom-from')?.value;
    const toStr = document.getElementById('export-custom-to')?.value;
    if (fromStr && toStr) {
      const fParts = fromStr.split('-');
      const tParts = toStr.split('-');
      periodText = `${fParts[2]}/${fParts[1]}/${fParts[0]} ~ ${tParts[2]}/${tParts[1]}/${tParts[0]}`;
      startDate = new Date(fromStr);
      endDate = new Date(toStr);
    } else {
      periodText = state.lang === 'en' ? 'Custom Date Range' : 'Συγκεκριμένες Ημερομηνίες';
    }
  }

  let count = 0;
  if (state.transactions && state.transactions.length) {
    const startStr = startDate ? formatISODateLocal(startDate) : null;
    const endStr = endDate ? formatISODateLocal(endDate) : null;
    count = state.transactions.filter(t => {
      if (!t.date) return false;
      const tDate = t.date.split('T')[0].split(' ')[0];
      if (startStr && tDate < startStr) return false;
      if (endStr && tDate > endStr) return false;
      return true;
    }).length;
  }

  const periodLabelEl = document.getElementById('export-step2-period-label');
  const countBadgeEl = document.getElementById('export-step2-count-badge');
  if (periodLabelEl) periodLabelEl.textContent = periodText;
  if (countBadgeEl) {
    const unit = state.lang === 'en' ? (count === 1 ? 'transaction' : 'transactions') : (count === 1 ? 'συναλλαγή' : 'συναλλαγές');
    countBadgeEl.textContent = `${count} ${unit}`;
  }
}

function goToExportStep2() {
  if (selectedExportPeriod === 'custom') {
    const fromStr = document.getElementById('export-custom-from')?.value;
    const toStr = document.getElementById('export-custom-to')?.value;
    if (!fromStr || !toStr) {
      alert(state.lang === 'en' ? 'Please select both start and end dates!' : 'Παρακαλώ επιλέξτε ημερομηνία έναρξης και λήξης!');
      return;
    }
    if (fromStr > toStr) {
      alert(state.lang === 'en' ? 'Start date must be before end date!' : 'Η ημερομηνία έναρξης πρέπει να είναι προγενέστερη της ημερομηνίας λήξης!');
      return;
    }
  }

  updateStep2Summary();

  const step1 = document.getElementById('export-step-1');
  const step2 = document.getElementById('export-step-2');
  if (step1) step1.style.display = 'none';
  if (step2) step2.style.display = 'block';
}
window.goToExportStep2 = goToExportStep2;

function selectExportOption(option, userInitiated = true) {
  selectedExportPeriod = option;

  const options = ['current-month', 'prev-month', 'current-year', 'prev-year', 'all', 'custom'];
  options.forEach(opt => {
    const el = document.getElementById(`export-opt-${opt}`);
    if (el) {
      el.classList.toggle('active', opt === option);
    }
  });

  const customContainer = document.getElementById('export-custom-range-container');
  const nextBtnContainer = document.getElementById('export-next-btn-container');

  if (option === 'custom') {
    if (customContainer) customContainer.style.display = 'flex';
    if (nextBtnContainer) nextBtnContainer.style.display = 'block';
  } else {
    if (customContainer) customContainer.style.display = 'none';
    if (nextBtnContainer) nextBtnContainer.style.display = 'none';

    if (userInitiated) {
      setTimeout(() => goToExportStep2(), 150);
    }
  }
}

function selectExportFormat(format) {
  selectedExportFormat = format;

  const formats = ['xlsx', 'csv', 'ods', 'json', 'pdf'];
  formats.forEach(f => {
    const el = document.getElementById(`export-format-${f}`);
    if (el) {
      el.classList.toggle('active', f === format);
    }
  });
}

function confirmExcelExport() {
  const now = new Date();
  let startDate = null;
  let endDate = null;

  if (selectedExportPeriod === 'current-month') {
    startDate = new Date(now.getFullYear(), now.getMonth(), 1);
    endDate = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  } else if (selectedExportPeriod === 'prev-month') {
    startDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    endDate = new Date(now.getFullYear(), now.getMonth(), 0);
  } else if (selectedExportPeriod === 'current-year') {
    startDate = new Date(now.getFullYear(), 0, 1);
    endDate = now;
  } else if (selectedExportPeriod === 'prev-year') {
    startDate = new Date(now.getFullYear() - 1, 0, 1);
    endDate = new Date(now.getFullYear() - 1, 11, 31);
  } else if (selectedExportPeriod === 'custom') {
    const fromStr = document.getElementById('export-custom-from').value;
    const toStr = document.getElementById('export-custom-to').value;
    if (!fromStr || !toStr) {
      alert(state.lang === 'en' ? 'Please select both start and end dates!' : 'Παρακαλώ επιλέξτε ημερομηνία έναρξης και λήξης!');
      return;
    }
    if (fromStr > toStr) {
      alert(state.lang === 'en' ? 'Start date must be before end date!' : 'Η ημερομηνία έναρξης πρέπει να είναι προγενέστερη της ημερομηνίας λήξης!');
      return;
    }
    exportToExcel(fromStr, toStr);
    return;
  }

  const startStr = startDate ? formatISODateLocal(startDate) : null;
  const endStr = endDate ? formatISODateLocal(endDate) : null;

  exportToExcel(startStr, endStr);
}

function exportToExcel(startDate = null, endDate = null) {
  if (!state.transactions.length) {
    const msg = state.lang === 'en' ? 'No transactions to export!' : 'Δεν υπάρχουν συναλλαγές!';
    alert(msg);
    return;
  }

  let transactionsToExport = state.transactions;
  if (startDate || endDate) {
    transactionsToExport = state.transactions.filter(t => {
      if (!t.date) return false;
      const tDate = t.date.split('T')[0].split(' ')[0];
      if (startDate && tDate < startDate) return false;
      if (endDate && tDate > endDate) return false;
      return true;
    });
  }

  if (!transactionsToExport.length) {
    const msg = TRANSLATIONS[state.lang]['export_no_data_range'] || 'Δεν υπάρχουν συναλλαγές σε αυτή την περίοδο!';
    alert(msg);
    return;
  }

  const rows = transactionsToExport.map(t => ({
    'Ημερομηνία': t.date, 'Τύπος': t.type === 'expense' ? 'Expense' : (t.type === 'income' ? 'Income' : 'Transfer'),
    'Ποσό': t.amount, 'Κατηγορία': t.category, 'Υποκατηγορία': t.subcategory || '',
    'Λογαριασμός': t.account_from, 'Σημείωση': t.note || '',
  }));

  const format = selectedExportFormat || 'xlsx';
  const baseName = `Budget_Assistant_Export_${new Date().toISOString().split('T')[0]}`;

  // JSON export does not require the SheetJS library.
  if (format === 'json') {
    try {
      const jsonStr = JSON.stringify(transactionsToExport, null, 2);
      const blob = new Blob([jsonStr], { type: 'application/json;charset=utf-8;' });
      downloadBlob(blob, `${baseName}.json`);
      closeExportPeriodSheet();
      return;
    } catch (err) {
      console.error('[export] JSON export failed.', err);
      alert(state.lang === 'en' ? 'JSON export failed!' : 'Η εξαγωγή JSON απέτυχε!');
      return;
    }
  }

  // PDF export: generate a simple, readable table-based PDF without external libs.
  if (format === 'pdf') {
    try {
      const blob = generatePdfBlob(rows, baseName);
      downloadBlob(blob, `${baseName}.pdf`);
      closeExportPeriodSheet();
      return;
    } catch (err) {
      console.error('[export] PDF export failed.', err);
      alert(state.lang === 'en' ? 'PDF export failed!' : 'Η εξαγωγή PDF απέτυχε!');
      return;
    }
  }

  // Guard: if the SheetJS library is not loaded, fall back to CSV so the export still works.
  if (typeof XLSX === 'undefined' || !XLSX || !XLSX.utils) {
    console.warn('[export] XLSX library not available, falling back to CSV export.');
    exportRowsAsCSV(rows, `${baseName}.csv`);
    closeExportPeriodSheet();
    return;
  }

  try {
    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Συναλλαγές');
    // Generate the file as a Blob instead of using XLSX.writeFile, because
    // writeFile relies on an <a>.click() download which silently fails inside
    // the Capacitor/Android WebView. We route the Blob through downloadBlob()
    // which uses the native Share sheet on mobile.
    if (format === 'csv') {
      const csvStr = XLSX.utils.sheet_to_csv(ws);
      const blob = new Blob(['\uFEFF' + csvStr], { type: 'text/csv;charset=utf-8;' });
      downloadBlob(blob, `${baseName}.csv`);
    } else {
      const bookType = format === 'ods' ? 'ods' : 'xlsx';
      const wbout = XLSX.write(wb, { bookType: bookType, type: 'array' });
      const mime = bookType === 'ods'
        ? 'application/vnd.oasis.opendocument.spreadsheet'
        : 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
      const blob = new Blob([wbout], { type: mime });
      downloadBlob(blob, `${baseName}.${bookType}`);
    }
  } catch (err) {
    console.error('[export] Spreadsheet export failed, falling back to CSV export.', err);
    exportRowsAsCSV(rows, `${baseName}.csv`);
  }
  closeExportPeriodSheet();
}

// Generate a valid, dependency-free PDF document from the export rows.
// Uses PDF content-stream text operators (BT/Tf/Td/Tj) to draw a simple table.
function generatePdfBlob(rows, baseName) {
  const headers = Object.keys(rows[0] || {});
  const pageWidth = 612;
  const pageHeight = 792;
  const margin = 40;
  const fontSize = 8;
  const lineHeight = 12;
  const colWidth = Math.floor((pageWidth - margin * 2) / Math.max(headers.length, 1));

  // Escape a string for a PDF literal string (parentheses and backslashes).
  const escPdf = (v) => String(v == null ? '' : v).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');

  // Truncate text to fit the column width (approx 5.5 chars per 8pt char per 44px col).
  const fit = (v) => {
    const s = String(v == null ? '' : v);
    const maxChars = Math.max(1, Math.floor(colWidth / 4.8));
    return s.length > maxChars ? s.substring(0, maxChars - 1) + '…' : s;
  };

  let content = '';
  let y = pageHeight - margin;

  const drawLine = (cells, bold) => {
    if (y < margin) return; // skip overflow (single page)
    content += 'BT /F' + (bold ? '2' : '1') + ' ' + fontSize + ' Tf ' + margin + ' ' + y + ' Td\n';
    cells.forEach((c, i) => {
      const x = i * colWidth;
      content += '1 0 0 1 ' + x + ' 0 Tm (' + escPdf(fit(c)) + ') Tj\n';
    });
    content += 'ET\n';
    y -= lineHeight;
  };

  // Title
  content += 'BT /F2 14 Tf ' + margin + ' ' + y + ' Td (' + escPdf(baseName) + ') Tj ET\n';
  y -= 20;

  // Header row
  drawLine(headers, true);
  // Separator line
  content += '0.7 w ' + margin + ' ' + (y + 3) + ' m ' + (pageWidth - margin) + ' ' + (y + 3) + ' l S\n';
  y -= 4;

  // Data rows
  rows.forEach(r => {
    drawLine(headers.map(h => r[h]), false);
  });

  const objects = [];
  const addObj = (body) => {
    objects.push(body);
    return objects.length;
  };
  addObj('<< /Type /Catalog /Pages 2 0 R >>');
  addObj('<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
  addObj('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ' + pageWidth + ' ' + pageHeight + '] /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> /Contents 7 0 R >>');
  addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
  addObj('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
  addObj('<< /Length ' + content.length + ' >>\nstream\n' + content + 'endstream');

  let pdf = '%PDF-1.4\n';
  const offsets = [];
  objects.forEach((body, i) => {
    offsets.push(pdf.length);
    pdf += (i + 1) + ' 0 obj\n' + body + '\nendobj\n';
  });
  const xrefPos = pdf.length;
  pdf += 'xref\n0 ' + (objects.length + 1) + '\n';
  pdf += '0000000000 65535 f \n';
  offsets.forEach(off => {
    pdf += String(off).padStart(10, '0') + ' 00000 n \n';
  });
  pdf += 'trailer\n<< /Size ' + (objects.length + 1) + ' /Root 1 0 R >>\nstartxref\n' + xrefPos + '\n%%EOF';

  return new Blob([pdf], { type: 'application/pdf' });
}

// Convert a Blob to a base64 data URL string (needed by the Capacitor
// Filesystem plugin, which cannot write raw Blob objects directly).
function blobToBase64(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const dataUrl = reader.result;
      // Strip the "data:<mime>;base64," prefix to get the raw base64 payload.
      const commaIdx = dataUrl.indexOf(',');
      resolve(commaIdx >= 0 ? dataUrl.substring(commaIdx + 1) : dataUrl);
    };
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(blob);
  });
}

// Robust download helper that works in browsers AND Capacitor/Android WebViews.
// On native (Capacitor) platforms, <a>.click() blob downloads are silently
// blocked, so we write the file to the app cache via the Capacitor Filesystem
// plugin and open the native share sheet via the Capacitor Share plugin. This
// is the most reliable mechanism on Android WebView.
function downloadBlob(blob, fileName) {
  const isNative = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());

  // 1) Native / WebView: Capacitor Filesystem + Share plugins.
  if (isNative) {
    const Filesystem = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Filesystem;
    const Share = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Share;
    if (Filesystem && Share && typeof Filesystem.writeFile === 'function' && typeof Share.share === 'function') {
      try {
        blobToBase64(blob).then(async (base64) => {
          const safeName = fileName.replace(/[^\w.\-]+/g, '_');
          const result = await Filesystem.writeFile({
            path: safeName,
            data: base64,
            directory: 'CACHE',
            recursive: true
          });
          const fileUri = result && result.uri ? result.uri : safeName;
          await Share.share({
            title: fileName,
            files: [fileUri],
            dialogTitle: fileName
          });
        }).catch(err => {
          console.warn('[export] Capacitor Filesystem/Share failed, falling back to Web Share API.', err);
          shareViaWebApi(blob, fileName);
        });
        return true;
      } catch (err) {
        console.warn('[export] Capacitor Filesystem/Share threw, falling back to Web Share API.', err);
      }
    }
  }

  // 2) Native / WebView fallback: Web Share API with a File object.
  if (isNative && navigator.share) {
    try {
      const file = new File([blob], fileName, { type: blob.type || 'application/octet-stream' });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        navigator.share({ files: [file], title: fileName }).catch(err => {
          console.warn('[export] Web Share API canceled or failed:', err);
        });
        return true;
      }
    } catch (err) {
      console.warn('[export] Web Share API failed, falling back to anchor download.', err);
    }
  }

  // 3) Standard browser / fallback: anchor element download.
  try {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    return true;
  } catch (err) {
    console.error('[export] downloadBlob failed.', err);
    return false;
  }
}

// Web Share API fallback used when the Capacitor plugins are unavailable.
function shareViaWebApi(blob, fileName) {
  if (navigator.share) {
    try {
      const file = new File([blob], fileName, { type: blob.type || 'application/octet-stream' });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        navigator.share({ files: [file], title: fileName }).catch(err => {
          console.warn('[export] Web Share API canceled or failed:', err);
        });
        return;
      }
    } catch (err) {
      console.warn('[export] Web Share API failed:', err);
    }
  }
  // Last-resort anchor download.
  try {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  } catch (err) {
    console.error('[export] shareViaWebApi anchor download failed.', err);
  }
}

// Fallback CSV export used when the XLSX library is unavailable or fails.
function exportRowsAsCSV(rows, fileName) {
  const headers = Object.keys(rows[0] || {});
  const escapeCell = (v) => {
    const s = String(v == null ? '' : v);
    return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const lines = [headers.map(escapeCell).join(',')];
  rows.forEach(r => {
    lines.push(headers.map(h => escapeCell(r[h])).join(','));
  });
  const csv = '\uFEFF' + lines.join('\r\n'); // BOM for Excel compatibility
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  downloadBlob(blob, fileName);
}

