function selectInviteRole(role) {
  const memberCard = document.getElementById('role-card-member');
  const adminCard = document.getElementById('role-card-admin');
  const hiddenInput = document.getElementById('invite-role-select');
  const memberCheck = document.getElementById('role-check-member');
  const adminCheck = document.getElementById('role-check-admin');
  const memberDetails = document.getElementById('role-permission-member');
  const adminDetails = document.getElementById('role-permission-admin');

  const selectCard = (card, selected) => {
    if (!card) return;
    if (selected) {
      card.style.border = '2px solid var(--accent)';
      card.style.background = 'rgba(var(--accent-rgb,124,106,247),0.10)';
      card.style.boxShadow = '0 0 0 3px rgba(var(--accent-rgb,124,106,247),0.18)';
      card.style.opacity = '1';
    } else {
      card.style.border = '2px dashed var(--card-border)';
      card.style.background = 'var(--card-bg2,rgba(255,255,255,0.03))';
      card.style.boxShadow = 'none';
      card.style.opacity = '0.75';
    }
  };

  if (role === 'member') {
    selectCard(memberCard, true);
    selectCard(adminCard, false);
    if (memberCheck) memberCheck.style.opacity = '1';
    if (adminCheck) adminCheck.style.opacity = '0';
    if (memberDetails) memberDetails.style.display = 'block';
    if (adminDetails) adminDetails.style.display = 'none';
    if (hiddenInput) hiddenInput.value = 'member';
  } else {
    selectCard(memberCard, false);
    selectCard(adminCard, true);
    if (memberCheck) memberCheck.style.opacity = '0';
    if (adminCheck) adminCheck.style.opacity = '1';
    if (memberDetails) memberDetails.style.display = 'none';
    if (adminDetails) adminDetails.style.display = 'block';
    if (hiddenInput) hiddenInput.value = 'admin';
  }
}
async function forceAppUpdate() {
  const confirmMsg = state.lang === 'en' ? 'Force update and reload the app?' : 'Θέλετε να επιβάλλετε ενημέρωση και επαναφόρτωση της εφαρμογής;';
  const confirmed = await showConfirm(confirmMsg, state.lang === 'el' ? 'Αναγκαστική Ενημέρωση' : 'Force Update', '🔄');
  if (!confirmed) return;

  if (typeof showSyncToast === 'function') {
    showSyncToast(state.lang === 'el' ? 'Έλεγχος & λήψη ενημέρωσης...' : 'Checking & downloading update...', 10000);
  }

  if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.CapacitorUpdater) {
    try {
      const manifestRes = await fetch("https://budget-assistant-pwa.pages.dev/version.json?_t=" + Date.now());
      const manifest = await manifestRes.json();

      if (!manifest || !manifest.url) {
        throw new Error("Invalid version.json format");
      }

      if (typeof showSyncToast === 'function') {
        showSyncToast((state.lang === 'el' ? 'Λήψη έκδοσης ' : 'Downloading version ') + (manifest.version || 'νέας') + '...', 10000);
      }

      // Wrap the native download in a timeout so it can never hang forever
      // (Capgo's download() has no built-in timeout and can stall silently,
      // leaving the user stuck on "Downloading version...").
      const DOWNLOAD_TIMEOUT_MS = 90000;
      const downloadPromise = window.Capacitor.Plugins.CapacitorUpdater.download({
        url: manifest.url,
        version: manifest.version || Date.now().toString(),
        checksum: manifest.checksum || undefined
      });
      const update = await Promise.race([
        downloadPromise,
        new Promise((_, reject) => setTimeout(() => reject(new Error('Download timed out')), DOWNLOAD_TIMEOUT_MS))
      ]);

      await window.Capacitor.Plugins.CapacitorUpdater.set({ id: update.id });

      if (typeof showSyncToast === 'function') {
        showSyncToast(state.lang === 'el' ? 'Εφαρμογή ενημέρωσης & επανεκκίνηση...' : 'Applying update & reloading...', 3000);
      }

      setTimeout(async () => {
        try {
          if (window.Capacitor.Plugins.CapacitorUpdater.reload) {
            await window.Capacitor.Plugins.CapacitorUpdater.reload();
          } else {
            window.location.reload(true);
          }
        } catch (_) {
          window.location.reload(true);
        }
      }, 500);
      return;
    } catch (e) {
      console.error('[ForceUpdate] Capgo update failed; falling back to classic reload:', e);
    }
  }

  // Classic path (plain web/PWA or no OTA update available): clear SW + cache
  // and reload the bundled app.
  if ('serviceWorker' in navigator) {
    try {
      const registrations = await navigator.serviceWorker.getRegistrations();
      for (let registration of registrations) {
        await registration.unregister();
      }
    } catch (e) {
      console.error('Failed to unregister SW:', e);
    }
  }
  if ('caches' in window) {
    try {
      const keys = await caches.keys();
      for (let key of keys) {
        await caches.delete(key);
      }
    } catch (e) {
      console.error('Failed to clear cache:', e);
    }
  }
  window.location.reload(true);
}

